              "editor": "<p style='text-align:center;color:rgba(255,255,255,0.6);font-size:14px;'><i class='far fa-calendar-alt'></i> March 10, 2026 &nbsp;&bull;&nbsp; <i class='far fa-user'></i> Dr. Michael Carter &nbsp;&bull;&nbsp; <i class='far fa-clock'></i> 5 min read</p>"
            }
